mapper.select:
		select count(*) from chb_equ_sub sub
		/***三期CHB_SUBMIT_STATUS去除改造  20220310**/
		/*left join CHB_SUBMIT_STATUS status
    		on sub.sumit_seq = status.seqno*/
		/***三期CHB_SUBMIT_STATUS去除改造  20220310**/


		 	sub.REGIST_BANK_CODE LIKE concat(concat('%',#{bankCode}),'%')



			 	 #{orgCode}




             		#{status}



		 	AND sub.INDENTIFY_MARK LIKE concat(concat('%',#{indentifyMark}),'%')



             		#{personalIdentifyType}




             		#{institutionIdentifyType}



		 	AND sub.HOLDER_NAME LIKE concat(concat('%',#{holderName}),'%')


		 	AND sub.IDENTIFY_NUMBER LIKE concat(concat('%',#{identifyNumber}),'%')


		 	AND sub.ORG_INDENTIFY_MARK LIKE concat(concat('%',#{orgIndentifyMark}),'%')

				/***三期CHB_SUBMIT_STATUS去除改造  20220310**/


             		#{submitFeedbackStatus}

				/***三期CHB_SUBMIT_STATUS去除改造  20220310**/



             		#{submitStatus}




             		#{holderType,jdbcType=VARCHAR}



				AND to_char(sub.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDate}


				AND to_char(sub.SUBMIT_TIME,'yyyy-MM-dd') <=#{submitDateEnd}


		 	AND to_char(sub.UPDATE_TIME,'yyyy-MM-dd') >= #{updateTime}


		 	AND to_char(sub.UPDATE_TIME,'yyyy-MM-dd') <= #{updateTimeEnd}


		 	AND sub.CHB_SUBMIT_DEADLINE >= to_date(#{submitDeadLineStart},'yyyy-MM-dd HH24:mi:ss')


		 	AND sub.CHB_SUBMIT_DEADLINE <= to_date(#{submitDeadLineEnd},'yyyy-MM-dd HH24:mi:ss')


		ORDER BY sub.UPDATE_TIME DESC, sub.INDENTIFY_MARK ASC

SELECT * FROM ( SELECT tmp_page.*, ROWNUM row_id FROM ( select INDENTIFY_MARK as indentifyMark, ORG_INDENTIFY_MARK as orgIndentifyMark, REGIST_BANK_CODE as bankCode, IS_BELONG_BANK as isBelongBank, THE_BANK_NAME as theBankName, THE_BANK_CODE as theBankCode, HOLDER_MARK as holderMark, HOLDER_REGION as holderRegion, HOLDER_TYPE as holderType, nvl(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE) identifyType, PERSONAL_IDENTIFY_TYPE as personalIdentifyType, INSTITUTION_IDENTIFY_TYPE as institutionIdentifyType, nvl(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE) as IDENTIFY_TYPE, OTHER_IDENTIFY_NAME as otherIdentifyName, IDENTIFY_NUMBER as identifyNumber, SPV_CAP_ACC_BANK as spvCapAccBank, OTHER_CAP_ACC_BANK as otherCapAccBank, SPV_REGIST_CODE as spvRegistCode, HOLDER_DATE holderDate, HOLDER_NAME holderName, HOLDER_SEX holderSex, HOLDER_RISK_PREFER as holderRiskPrefer, HOLDER_CELLPHONE as holderCellphone, HOLDER_TELEPHONE as holderTelephone, HOLDER_EMAIL as holderEmail, TYPE as type, REMARK, SUMIT_SEQ sumitSeq, SUBMIT_STATUS as submitStatus, SUBMIT_TIME as submitTime, CHB_SUBMIT_DEADLINE as chbSubmitDeadline, SUBMIT_DEADLINE as submitDeadline, STATUS as status, sub.UPDATE_TIME as updateTime, sub.ORG_CODE orgCode, status.SUBMIT_FEEDBACK_STATUS as submitFeedbackStatus, sub.CHECK_SEQNO as checkSeqno from chb_equ_sub sub /***三期CHB_SUBMIT_STATUS去除改造 20220310**/ /*left join CHB_SUBMIT_STATUS status on sub.sumit_seq = status.seqno*/ /***三期CHB_SUBMIT_STATUS去除改造 20220310**/
sub.REGIST_BANK_CODE LIKE concat(concat('%',#{bankCode}),'%')
#{orgCode}
#{status}
AND sub.INDENTIFY_MARK LIKE concat(concat('%',#{indentifyMark}),'%')
#{personalIdentifyType}
#{institutionIdentifyType}
AND sub.HOLDER_NAME LIKE concat(concat('%',#{holderName}),'%')
AND sub.IDENTIFY_NUMBER LIKE concat(concat('%',#{identifyNumber}),'%')
AND sub.ORG_INDENTIFY_MARK LIKE concat(concat('%',#{orgIndentifyMark}),'%')
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/
#{submitFeedbackStatus}
/***三期CHB_SUBMIT_STATUS去除改造 20220310**/
#{submitStatus}
#{holderType,jdbcType=VARCHAR}
AND to_char(sub.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDate}
AND to_char(sub.SUBMIT_TIME,'yyyy-MM-dd') <=#{submitDateEnd}
AND to_char(sub.UPDATE_TIME,'yyyy-MM-dd') >= #{updateTime}
AND to_char(sub.UPDATE_TIME,'yyyy-MM-dd') <= #{updateTimeEnd}
AND sub.CHB_SUBMIT_DEADLINE >= to_date(#{submitDeadLineStart},'yyyy-MM-dd HH24:mi:ss')
AND sub.CHB_SUBMIT_DEADLINE <= to_date(#{submitDeadLineEnd},'yyyy-MM-dd HH24:mi:ss')
order by sub.CHB_SUBMIT_DEADLINE,sub.INDENTIFY_MARK,sub.REGIST_BANK_CODE,sub.SUBMIT_STATUS desc )tmp_page ) WHERE row_id <= #{end} AND row_id > #{start}
